<?php
namespace qqworld_collector\module\collect_filter; use qqworld_collector\lib; class qqworld_collector_parse_mparticle_uc_cn_post_content extends lib { var $post_content = array(); public function __construct() { add_filter( 'qqworld-collector-parse-mparticle-uc-cn-post-content', array($this, 'filter'), 10, 6 ); } public function filter($item, $source_link, $html, $type, $item_args, $download_args) { $json = json_decode($item, true); if ($json) { $preg = preg_match_all('/<\!\-\-\{img:(\d)\}\-\->/i', $json['text'], $matches); if ($preg) { $inner_imgs = $json['inner_imgs']; foreach ($matches[0] as $index => $img) { $inner_img = $inner_imgs[$matches[1][$index]]; $json['text'] = str_replace($img, '<img src="'.$inner_img['url'].'" width="'.$inner_img['width'].'" height="'.$inner_img['height'].'" />', $json['text']); } } $item = $json['text']; } return $item; } } new qqworld_collector_parse_mparticle_uc_cn_post_content; ?>